function renderAdmin(state) {
  const views = { overview: overview(state), plans: plansPage(state), orders: ordersPage(state), subscriptions: subscriptionPage(state), audit: auditPage(state), settings: settingsPage(state) };
  return adminFrame(state, views[state.activeTab] || views.overview);
}

function drawerContent(state, kind, id) {
  if (kind === 'plan') return { title: id ? 'Refine this plan' : 'Shape a payment plan', kicker: id ? 'EDIT PLAN' : 'NEW PLAN', content: planForm(state.plans.find(p => p.id === id) || null), wide: false };
  if (kind === 'order') {
    const order = state.orders.find(o => o.id === id) || state.orders[0];
    return { title: 'Order schedule', kicker: 'MADE TO ORDER', content: orderDrawer(order), wide: false };
  }
  return null;
}

