  const paymentSummary = choice === 'full'
    ? `<div class="breakdown-row"><span>Pay today</span><strong>${money(price)}</strong></div><div class="breakdown-row breakdown-muted"><span>Balance due later</span><strong>$0.00 AUD</strong></div>`
    : choice === 'installment'
      ? `<div class="installment-list"><div><span class="inst-number inst-done">1</span><span><strong>Today</strong><small>Reserve your piece</small></span><b>${money(split[0])}</b></div><div><span class="inst-number">2</span><span><strong>In 2 weeks</strong><small>While it takes shape</small></span><b>${money(split[1])}</b></div><div><span class="inst-number">3</span><span><strong>In 4 weeks</strong><small>Before dispatch</small></span><b>${money(split[2])}</b></div></div><div class="breakdown-total"><span>3 payments · exact total</span><strong>${money(price)}</strong></div>`
      : `<div class="breakdown-row"><span>${icon('check')} Due today · 30% deposit</span><strong>${money(deposit)}</strong></div><div class="breakdown-row"><span>${icon('clock')} Before dispatch · balance</span><strong>${money(balance)}</strong></div><div class="breakdown-total"><span>Order total</span><strong>${money(price)}</strong></div>`;
